"""Data model for generated files. Everything a generator returns is an Artifact; the engine returns a Bundle."""
from dataclasses import dataclass, field, asdict

HEADER = "Generated by InfraLoop from the scan of your repository. Review before use: nothing here was run against your app."


@dataclass
class Artifact:
    path: str                      # where the file belongs in the repository, relative to its root
    content: str
    gap: str                       # the gap (issue id) this file addresses; "" for a helper file
    title: str                     # short human label, for example "Dockerfile for the Python service in ."
    confidence: str = "medium"     # high | medium | low: how sure the template is that it fits this project
    assumptions: list = field(default_factory=list)   # what the template had to guess from the scan facts
    review: list = field(default_factory=list)        # what the user must check or fill in before using the file

    def to_dict(self):
        return asdict(self)


@dataclass
class Skipped:
    gap: str
    reason: str

    def to_dict(self):
        return asdict(self)


@dataclass
class Advice:
    """A fix for a file the repository already has. Never applied by InfraLoop: it is only written into MANIFEST.md."""
    gap: str
    title: str
    found: str = ""                # the gap's own detail from the scan
    steps: list = field(default_factory=list)
    snippet: str = ""
    snippet_lang: str = ""

    def to_dict(self):
        return asdict(self)


@dataclass
class Bundle:
    files: list = field(default_factory=list)      # list[Artifact]: new files
    advice: list = field(default_factory=list)     # list[Advice]: fixes for existing files, applied by hand
    skipped: list = field(default_factory=list)    # list[Skipped]: gaps that no generator covers, with the reason
    target: dict = field(default_factory=dict)     # the 'where will it run?' option the user picked, if any
    brief: str = ""                                # plain-language 'Your chosen setup' text, written to SETUP.md
    implementation: str = ""                       # ordered 'what to do next' steps, written to IMPLEMENTATION.md

    def to_dict(self):
        return {"files": [f.to_dict() for f in self.files], "advice": [a.to_dict() for a in self.advice],
                "skipped": [s.to_dict() for s in self.skipped], "target": self.target, "brief": self.brief,
                "implementation": self.implementation}
